# Wilson intervals describe each route; paired difference uncertainty remains separately registered.
def pct(x):return f'{100*x:.2f}%'
def wilson(k,n):
 z=1.959963984540054;p=k/n;b=1+z*z/n;c=(p+z*z/(2*n))/b;h=z*math.sqrt(p*(1-p)/n+z*z/(4*n*n))/b;return f'{pct(c-h)}–{pct(c+h)}'
def table(head,rows):return '<div class="tw"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
